#!/usr/bin/env bash
# Run the complete local acceptance path. All fixtures are generated by Go.
set -euo pipefail

export PATH="$(go env GOPATH)/bin:${PATH}"
export GOMEMLIMIT="${GOMEMLIMIT:-32MiB}"

OUT="${1:-${TMPDIR:-/tmp}/media-demo}"

go1.25.6 mod tidy
go1.25.6 build ./...
go1.25.6 test ./...
go1.25.6 run ./cmd/mediacheck verify \
  --out "${OUT}" \
  --faults truncated,stale-index,rtp-wrap,slow-reader,crash-after-mux \
  --resume
